from pathlib import Path
import json,hashlib,csv,collections
from datetime import datetime,timezone
R=Path(__file__).resolve().parent;V=R.parent
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 a=json.loads((R/'AGREEMENT.json').read_text());v=json.loads((R/'VERIFICATION.json').read_text());f=json.loads((R/'RATING-FREEZE.json').read_text());recovery=json.loads((R/'TRANSPORT-RECOVERY-RECEIPT.json').read_text()) if (R/'TRANSPORT-RECOVERY-RECEIPT.json').exists() else None
 lines=['PROSPECTIVE IN IMAGE VARIABLE ONLY — text events exposed (v100/v102).','Two independent model picture-rating sets; initial agreement before adjudication/OT merge.','',f"Original calls:336; accepted page responses A{a['valid_page_responses']['A']}/168, B{a['valid_page_responses']['B']}/168.",f"Paired frozen physical lines: {a['paired_physical_lines']} / {a['registered_physical_lines']}. H/F are not duplicated observations."]
 for key in ['G6','G2']:
  g=a[key];lines.append(f"{key} ({g['governs']}): kappa={g['kappa']} ({g.get('exact_kappa')}); {g['gate_status']}.")
 if a['paired_physical_lines']<a['registered_physical_lines']:lines+=['','The displayed kappas describe complete pairs only. They are diagnostic and cannot pass either primary gate because some frozen registered lines lack paired valid ratings. Missing responses are never converted into NO.']
 lines+=['','G6 is six-way PL/VE/FG/CE/OT/NO before OT merge. G2 is PL/not-PL. Both use exact unweighted Cohen kappa>=0.60 on the initial two raters; no adjudication may rescue initial gates.','', 'Models:']
 for role,model in f['models'].items():lines.append(f'  {role}: {model}')
 lines+=['','Each call used a new process, random neutral workspace and session UUID; identical picture-only manual plus exactly one native source image. Settings/MCP/filesystem/command tools were disabled. StructuredOutput was the only available tool. Raters received no source identifiers, text/EVT, geometry, results, other page context or other rater response. A shared vendor/training distribution can still correlate errors; this is model agreement, not external ground truth.','','Original failure reasons:']
 for reason,n in v['original_failures'].items():lines.append(f'  {reason}: {n}')
 if recovery:lines+=['',f"Separately documented technical recovery: {recovery['calls']} no-annotation native failures, {sum(x['recovery_valid'] for x in recovery['records'])} accepted first semantic annotations. Original failures remain unchanged. This supplement was frozen during collection, before label derivation/kappa, not misrepresented as part of the original pre-collection freeze. No completed/invalid semantic response was repeated or repaired."]
 lines+=['','COORDINATE LIMITATION: synthetic outlined-square checks identified OT but produced inaccurate boxes. All those failures are preserved in SYNTHETIC-COORDINATE-RECEIPTS.json. Schema/provenance checks do not qualify coordinate accuracy, and agreement does not establish truthful image context. The user explicitly authorized proceeding with this limitation.','', 'TIMING EXCEPTION: v4.2 was not frozen before initial registration. The retained45 source lines and subsequent source review were kept with that exception; this collection did not alter the1145-line geometry.','','Nearest context: native edge-to-edge rectangle distance divided by frozen line-box height; nearest category within2 heights, otherwise NO. Edge-distance ties use center distance, area and geometry only, never category priority. Exact coincident boxes with conflicting categories invalidate a page. Normalized bounds are checked without clipping or analyst repair. No pictures on a complete page is a legitimate NO context.','','Confusion matrices:']
 for key in ['G6','G2']:
  g=a[key];lines.append(key+' categories: '+', '.join(g['categories']));lines.extend('  '+str(row) for row in g['confusion_matrix'])
 lines+=['','Raw responses, original failures and model/session/hash receipts retained. Agreement.json and LINE-CONTEXT-A/B.csv contain the category/line crosswalk; no text outcomes are joined.','Adjudication, OT merge, support, scientific controls, H-IMG/H-PLANT tests and outcome joins were NOT RUN. v103 remains parked; no Rosettes leave-out grids.']
 (R/'REPORT.txt').write_text('\n'.join(lines)+'\n',encoding='utf-8')
 root=json.loads((V/'STATUS.json').read_text());root.update(picture_rating='ORIGINAL PLANNED CALLS COMPLETE; FAILURES RETAINED',rating_valid_pages=a['valid_page_responses'],G6=a['G6']['gate_status'],G2=a['G2']['gate_status'],adjudication='NOT RUN',rating_report='ratings/REPORT.txt',timing_exception_preserved=True);(V/'STATUS.json').write_text(json.dumps(root,indent=2)+'\n',encoding='utf-8')
 names=['RATING-FREEZE.json','AUTHORIZATION.json','AGREEMENT.json','LINE-CONTEXT-A.csv','LINE-CONTEXT-B.csv','VERIFICATION.json','REPORT.txt','STATUS.json','SYNTHETIC-COORDINATE-RECEIPTS.json','ENGINEERING.json','RATER-A.csv','RATER-B.csv','CALL-LEDGER.csv','EXPORT-RECEIPT.json','collect.py','agreement.py','verify_collection.py','report_agreement.py','export_raters.py','MANUAL-RATER.md','RESPONSE-SCHEMA.json','AUDIT-PARSER-REPAIR.json']
 if recovery:names+=['TRANSPORT-RECOVERY-FREEZE.json','TRANSPORT-RECOVERY-RECEIPT.json','TRANSPORT-RECOVERY-EXECUTION-REPAIR.json','recover_unstarted_calls.py','recover_unstarted_calls_original.py']
 seal=dict(status='TWO INITIAL RATER SETS AND PRE_ADJUDICATION AGREEMENT SEALED',utc=datetime.now(timezone.utc).isoformat(),files={n:sha(R/n) for n in names},data={str(p.relative_to(R)):sha(p) for folder in ['responses','attempts','raw','transport-recovery-v1'] for p in (R/folder).rglob('*') if p.is_file()},geometry_sha256=f['geometry_sha256'],manual_sha256=f['manual_sha256'],timing_exception=f['timing_exception'],coordinate_limit=f['coordinate_control_limit'],adjudication='NOT RUN',v103='PARKED')
 (R/'AGREEMENT-FINAL-SEAL.json').write_text(json.dumps(seal,indent=2)+'\n',encoding='utf-8');print(R/'REPORT.txt')
if __name__=='__main__':main()
